package util

import (
	"bufio"
	"os"
	"path/filepath"
	"strings"

	log "github.com/sirupsen/logrus"
)

// GeneratedHeader 는 Go / Kotlin / TypeScript / Dart 생성 파일의 첫 줄이다 (Go 의 생성 파일 규칙과 같은 형식).
const GeneratedHeader = "// Code generated by gomachine. DO NOT EDIT."

// RustGeneratedHeader 는 Rust 생성 파일의 첫 줄이다.
const RustGeneratedHeader = "// @generated by gomachine - do not edit"

// generatedPrefixes 는 생성 파일로 보는 첫 줄이다. 뒤 세 개는 예전 TypeScript 생성 파일의 머리줄이다.
var generatedPrefixes = []string{
	GeneratedHeader,
	RustGeneratedHeader,
	"// Auto-generated by buildtool-model",
	"// Auto-generated TypeScript types for ",
	"// Auto-generated Vue 3 composable for ",
}

// Force 가 true 면 머리줄이 없는 기존 파일도 덮어쓴다 (명령줄 --force).
var Force = false

// IsGeneratedContent 는 내용의 첫 줄이 생성 파일 머리줄인지 확인한다.
func IsGeneratedContent(content string) bool {
	line := content
	if i := strings.IndexByte(line, '\n'); i >= 0 {
		line = line[:i]
	}
	line = strings.TrimPrefix(strings.TrimRight(line, "\r"), "\ufeff")
	for _, p := range generatedPrefixes {
		if strings.HasPrefix(line, p) {
			return true
		}
	}
	return false
}

// IsGeneratedFile 은 파일 첫 줄이 생성 파일 머리줄인지 확인한다. 읽지 못하면 false.
func IsGeneratedFile(path string) bool {
	f, err := os.Open(path)
	if err != nil {
		return false
	}
	defer f.Close()
	line, _ := bufio.NewReader(f).ReadString('\n')
	return IsGeneratedContent(line)
}

// WriteGenerated 는 생성 파일을 쓴다 (디렉터리도 만든다). 이미 있는 파일에 머리줄이 없으면 사용자 파일로 보고
// 경고만 찍고 건너뛴다 (Force 면 덮어쓴다). 내용이 같으면 쓰지 않는다. 실제로 썼는지를 돌려준다.
func WriteGenerated(filename string, content string) (bool, error) {
	if _, err := os.Lstat(filename); err == nil && !Force && !IsGeneratedFile(filename) {
		log.Printf("WARNING: %s exists without the %q header (hand-written file?), skipped; remove it or run with --force to overwrite", filename, GeneratedHeader)
		return false, nil
	}
	if err := os.MkdirAll(filepath.Dir(filename), 0755); err != nil {
		return false, err
	}
	return WriteIfChanged(filename, content)
}

// SkippedUserFile 는 WriteGenerated 가 사용자 파일이라 건너뛸 파일인지 확인한다 (로그 없이).
func SkippedUserFile(filename string) bool {
	_, err := os.Lstat(filename)
	return err == nil && !Force && !IsGeneratedFile(filename)
}
